LEC=ref('US Prescribing Information: LEQEMBI, current DailyMed record','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9d1ff786-e577-410a-a273-c4d7d0e4e975')
DON=ref('US Prescribing Information: KISUNLA','https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=190352d4-ef62-4679-b4fa-e846e2766afa&type=display')
